#include <iostream>
#include <vector>
#include <bitset>
using namespace std;

const int MAXK = 20005;

// 返回最大可达的模值
int solveCase(int n, int k, const vector<int>& arr) {
    bitset<MAXK> dp;    // dp[r] = 1 表示模值 r 可达，只维护非空子序列
    bitset<MAXK> mask;  // 只保留前 k 位

    for (int i = 0; i < k; i++) {
        mask.set(i);
    }

    for (int num : arr) {
        int x = num % k;

        // 循环左移 x 位：高位溢出的部分补到低位
        bitset<MAXK> shifted;
        if (x == 0) {
            shifted = dp;
        } else {
            shifted = ((dp << x) & mask) | (dp >> (k - x));
        }

        dp |= shifted;   // 选择当前数接在已有方案后面
        dp.set(x);       // 单独选择当前数
        dp &= mask;      // 只保留前 k 位
    }

    // 从大到小找最大可达模值
    for (int ans = k - 1; ans >= 0; ans--) {
        if (dp.test(ans)) {
            return ans;
        }
    }
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n, k;
        cin >> n >> k;
        vector<int> arr(n);

        for (int i = 0; i < n; i++) {
            cin >> arr[i];
        }

        cout << solveCase(n, k, arr) << '\n';
    }

    return 0;
}
