        x = num % M
        shifted = rotate_left(dp, x, M, mask)
        dp |= shifted           # 将当前数接在已有方案后面
        dp |= (1 << x)          # 单独选择当前数
        dp &= mask              # 仅保留低 M 位

    # 从大到小寻找最大可行余数
    for ans in range(M - 1, -1, -1):
        if (dp >> ans) & 1:
            return ans
    return 0


def main():
