        n = data[idx]
        M = data[idx + 1]
        idx += 2
        arr = data[idx:idx + n]
        idx += n
        out.append(str(solve_case(n, M, arr)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
